// Generates src/global/base-css.ts: the small always-loaded global utilities
// (s-hidden, form classes, checkbox/toggle/scrollbar) used outside components.
const fs = require('fs');
const path = require('path');
const tailwindcss = require('tailwindcss');
const twPlugin = require('tailwindcss/plugin');
const core = require('@salla.sa/twilight-tailwind-theme/plugin-core');
const generatorGlobals = require('@salla.sa/twilight-tailwind-theme/generator-globals');
const globalUtilities = require('@salla.sa/twilight-tailwind-theme/global-utilities');
const tokens = require('@salla.sa/twilight-tailwind-theme/component-tokens');
const postcss = require(require.resolve('postcss', {
  paths: [path.dirname(require.resolve('tailwindcss/package.json'))],
}));

const names = new Set();
for (const group of [...globalUtilities, generatorGlobals]) {
  for (const key of Object.keys(group)) {
    const m = key.match(/^\.([\w-]+)/); // leading class (pseudo/descendant keys count too)
    if (m) names.add(m[1]);
  }
}

const basePlugin = twPlugin((api) => {
  core.handler(api);
  api.addUtilities(generatorGlobals);
}, core.config);

(async () => {
  const result = await postcss([tailwindcss({
    important: false,
    darkMode: 'class',
    corePlugins: { preflight: false, outline: false },
    content: [{ raw: '' }],
    safelist: [...names],
    theme: tokens,
    plugins: [basePlugin],
  })]).process('@tailwind utilities;', { from: undefined });

  const css = result.css.replace(/\n\s*/g, ''); // values never span lines
  const out = path.resolve(__dirname, '../global/base-css.ts');
  fs.writeFileSync(out, `// GENERATED by src/plugins/build-base-css.js. Do not edit.\nexport const BASE_CSS = ${JSON.stringify(css)};\n`);
  console.log('base-css.ts:', css.length, 'bytes');
})();
